shaderConfig.customCode:
float hash21(vec2 p){
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
float vnoise(vec2 p){
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i),                hash21(i + vec2(1.0, 0.0)), f.x),
               mix(hash21(i + vec2(0.0,1.0)), hash21(i + vec2(1.0, 1.0)), f.x), f.y);
}
float curtain(vec2 q, float h, float seed, float t, float b0, float b1){
    float x = q.x * 1.15
            + 0.30 * sin(h * 1.30 + t * 0.55 + seed)
            + 0.14 * sin(h * 2.90 - t * 0.41 + seed * 1.7);
    float w    = sin(x * 3.4 + 1.2 * sin(x * 1.3 + t * 0.30 + seed));
    float u    = 0.5 + 0.5 * w;
    float body = u * u * (0.35 + 0.65 * u);
    float haze = 0.30 + 0.70 * (0.5 + 0.5 * sin(x * 1.7 - 0.6));
    float rays = 0.70 + 0.30 * sin(x * 20.0
                 + 5.0 * vnoise(vec2(q.x * 2.0, h * 0.35 + t * 0.20)));
    float gap  = 0.28 + 0.72 * smoothstep(-0.35, 0.55,
                     sin(q.x * 0.85 + seed * 3.1 + t * 0.13));
    float vmask = smoothstep(b0, b0 + 0.22, h) * (1.0 - smoothstep(b1, b1 + 0.55, h));
    return (body * 0.75 + haze * 0.25) * rays * gap * vmask;
}
float starfield(vec2 p, float t){
    float s = 0.0;
    for (int i = 0; i < 2; i++){
        float fi = float(i);
        vec2  q  = p * (34.0 + fi * 52.0);
        q.y += t * (0.35 + fi * 0.50);
        vec2  id = floor(q), f = fract(q) - 0.5;
        float h  = hash21(id + fi * 19.7);
        if (h > 0.965){
            vec2  o  = vec2(hash21(id + 3.17), hash21(id + 7.71)) - 0.5;
            float d  = length(f - o * 0.55);
            float tw = 0.5 + 0.5 * sin(t * (1.2 + h * 5.0) + h * 40.0);
            s += (1.0 - smoothstep(0.0, 0.085, d)) * tw * (0.55 + 0.45 * fi);
        }
    }
    return s;
}
float ridge(float x, float sd){
    return 0.135 + 0.072 * sin(x * 1.7 + sd)
                  + 0.042 * sin(x * 3.3 - sd * 2.0)
                  + 0.022 * sin(x * 6.1 + sd * 3.0);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2  res = u_resolution;
    vec2  p   = (fragCoord * 2.0 - res) / min(res.x, res.y);
    float t   = u_time * u_speed;
    float au  = u_audio_bass;

    float HZ = -0.42;                     // horizon height in p units
    float h = p.y - HZ;                   // height above the horizon
    vec2  q = vec2(p.x, h);

    vec3 col = mix(vec3(0.030, 0.055, 0.105), vec3(0.006, 0.014, 0.040),
                   smoothstep(0.0, 1.15, h));
    col += vec3(0.82, 0.88, 1.0) * starfield(q, t) * 0.9 * smoothstep(0.0, 0.30, h);

    vec3 aur = vec3(0.0);
    for (int i = 0; i < 3; i++){
        float fi   = float(i);
        float c    = curtain(q, h, fi * 2.7, t + fi * 1.2, 0.02 + fi * 0.07, 0.62 + fi * 0.22);
        vec3  tint = mix(u_color1, u_accent, clamp(0.10 + fi * 0.40, 0.0, 1.0));
        aur += tint * c * (1.0 - fi * 0.16);
    }
    aur *= u_intensity * (1.0 + au * 0.9);
    col += aur * 0.36 + aur * aur * 0.18;

    vec2  mp = p - vec2(0.66, HZ + 0.86);
    float md = length(mp);
    col += vec3(1.00, 0.97, 0.90) * (1.0 - smoothstep(0.028, 0.034, md));
    col += vec3(0.55, 0.70, 1.00) * 0.045 / (0.02 + md * md * 20.0);

    float r1 = HZ + ridge(p.x, 1.7) * 0.75;
    float r2 = HZ + ridge(p.x, 4.1) * 0.45;
    if (h < r1){
        col = mix(col, vec3(0.030, 0.045, 0.085), 0.88);
        col += u_color1 * 0.10 * exp(-max(r1 - h, 0.0) * 26.0);
    }
    if (h < r2) col = mix(col, vec3(0.010, 0.016, 0.032), 0.92);

    if (h < 0.0){
        float d = -h;
        vec2  rp = vec2(p.x + 0.016 * sin(d * 34.0 - t * 1.5)
                             + 0.010 * sin(d * 71.0 + t * 1.1), d * 1.5);
        float refl = curtain(rp, rp.y, 2.7, t + 1.2, 0.04, 0.70)
                   + 0.65 * curtain(rp, rp.y, 5.4, t + 2.4, 0.00, 0.45);
        vec3 wat = vec3(0.006, 0.014, 0.032)
                 + u_color1 * refl * 0.42 * (1.0 - smoothstep(0.0, 0.62, d));
        float mr = -ridge(p.x, 1.7) * 0.75;
        wat = mix(wat, vec3(0.012, 0.018, 0.036),
                  1.0 - smoothstep(0.0, 0.012, abs(d - abs(mr))));
        col = mix(col, wat, smoothstep(0.0, 0.006, d));
    }

    col += u_color1 * 0.030 * exp(-abs(h) * 30.0);
    col *= 1.0 - 0.16 * dot(p * 0.55, p * 0.55);
    col  = pow(max(col, 0.0), vec3(0.88));
    fragColor = vec4(col, 1.0);
}

